//! Serializable document model shared with the TypeScript side (types generated by tsify).

use serde::{Deserialize, Serialize};
use tsify_next::Tsify;

#[derive(Serialize, Deserialize, Tsify, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum Mode {
    /// Letters are cut out of the slab (classic stencil).
    Negative,
    /// Letters are the mask; the background gets painted.
    Positive,
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Axis {
    pub tag: String,
    pub value: f32,
}
impl Default for Axis {
    fn default() -> Self {
        Self { tag: "wght".into(), value: 400.0 }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Arc {
    /// Radius of the baseline circle in mm.
    pub radius: f64,
    /// Text on the inside of the circle (reads along the bottom).
    pub inside: bool,
    /// Angle (deg) of the text's centre. 90 = top of the circle.
    pub center_angle: f64,
}
impl Default for Arc {
    fn default() -> Self {
        Self { radius: 80.0, inside: false, center_angle: 90.0 }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct TextObj {
    pub text: String,
    pub font: String,
    /// Em size in mm.
    pub size: f64,
    pub tracking: f64,
    /// Line pitch as a multiple of the em size.
    pub leading: f64,
    pub align: Align,
    pub kerning: bool,
    /// Thicken (+) or thin (-) every glyph by this many mm per side.
    pub weight: f64,
    pub variations: Vec<Axis>,
    pub arc: Option<Arc>,
}
impl Default for TextObj {
    fn default() -> Self {
        Self {
            text: "STENCIL".into(),
            font: "default".into(),
            size: 60.0,
            tracking: 0.0,
            leading: 1.15,
            align: Align::Center,
            kerning: true,
            weight: 0.0,
            variations: vec![],
            arc: None,
        }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum Content {
    Text(TextObj),
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Obj {
    pub id: String,
    pub visible: bool,
    pub x: f64,
    pub y: f64,
    /// Degrees, counter-clockwise.
    pub rotation: f64,
    pub scale: f64,
    pub content: Content,
}
impl Default for Obj {
    fn default() -> Self {
        Self { id: "obj1".into(), visible: true, x: 0.0, y: 0.0, rotation: 0.0, scale: 1.0, content: Content::Text(TextObj::default()) }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum SlabShape {
    Rect,
    Rounded,
    Chamfer,
    Ellipse,
    Pill,
    /// Follows the content outline.
    Contour,
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Margins {
    pub top: f64,
    pub right: f64,
    pub bottom: f64,
    pub left: f64,
}
impl Default for Margins {
    fn default() -> Self {
        Self { top: 15.0, right: 15.0, bottom: 15.0, left: 15.0 }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Slab {
    pub shape: SlabShape,
    /// Fit the slab around the content using `margins`; otherwise use `width` x `height`.
    pub fit: bool,
    pub width: f64,
    pub height: f64,
    pub margins: Margins,
    /// Corner radius / chamfer size.
    pub radius: f64,
    /// Positive mode only: width of the surrounding frame (0 = none).
    pub frame: f64,
    pub mount_holes: bool,
    pub hole_diameter: f64,
    pub hole_inset: f64,
}
impl Default for Slab {
    fn default() -> Self {
        Self {
            shape: SlabShape::Rounded,
            fit: true,
            width: 200.0,
            height: 100.0,
            margins: Margins::default(),
            radius: 8.0,
            frame: 6.0,
            mount_holes: false,
            hole_diameter: 4.0,
            hole_inset: 7.0,
        }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum BridgeKind {
    /// Full-thickness bridge (traditional stencil look).
    Classic,
    /// Raised bridge: paint flows underneath it.
    Floating,
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum Strategy {
    /// Shortest span across the gap.
    Shortest,
    /// Prefer a fixed angle (see `angle`).
    Angle,
    /// Prefer horizontal or vertical, whichever is shorter.
    Axis,
    /// Radiate away from the island centre.
    Radial,
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct ManualBridge {
    pub id: String,
    pub a: [f64; 2],
    pub b: [f64; 2],
    pub width: Option<f64>,
    pub kind: Option<BridgeKind>,
}
impl Default for ManualBridge {
    fn default() -> Self {
        Self { id: "m1".into(), a: [0.0, 0.0], b: [0.0, 0.0], width: None, kind: None }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Bridges {
    pub enabled: bool,
    pub kind: BridgeKind,
    pub width: f64,
    pub min_per_island: u32,
    pub strategy: Strategy,
    /// Degrees; used by `Angle`.
    pub angle: f64,
    /// Height of a floating bridge in mm (sits at the top of the slab).
    pub float_height: f64,
    pub max_length: f64,
    pub manual: Vec<ManualBridge>,
    /// Automatic bridges whose endpoints are near any of these points are dropped.
    pub suppressed: Vec<[f64; 2]>,
}
impl Default for Bridges {
    fn default() -> Self {
        Self {
            enabled: true,
            kind: BridgeKind::Classic,
            width: 1.6,
            min_per_island: 2,
            strategy: Strategy::Shortest,
            angle: 90.0,
            float_height: 0.8,
            max_length: 100.0,
            manual: vec![],
            suppressed: vec![],
        }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Edge {
    /// Widen the cut towards the spray side by this many mm (0 = straight walls).
    pub chamfer: f64,
    pub steps: u32,
}
impl Default for Edge {
    fn default() -> Self {
        Self { chamfer: 0.0, steps: 3 }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Print {
    pub min_wall: f64,
    pub layer_height: f64,
    /// Material density in g/cm3 (PLA 1.24).
    pub density: f64,
}
impl Default for Print {
    fn default() -> Self {
        Self { min_wall: 0.8, layer_height: 0.2, density: 1.24 }
    }
}

#[derive(Serialize, Deserialize, Tsify, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
#[tsify(into_wasm_abi, from_wasm_abi)]
pub struct Doc {
    pub mode: Mode,
    pub mirror: bool,
    pub thickness: f64,
    pub objects: Vec<Obj>,
    pub slab: Slab,
    pub bridges: Bridges,
    pub edge: Edge,
    pub print: Print,
}
impl Default for Doc {
    fn default() -> Self {
        Self {
            mode: Mode::Negative,
            mirror: false,
            thickness: 2.0,
            objects: vec![Obj::default()],
            slab: Slab::default(),
            bridges: Bridges::default(),
            edge: Edge::default(),
            print: Print::default(),
        }
    }
}
